## Summary

- Extract options into explicit `WebSearch20250305Options` interface instead of using `Parameters<>` utility type
- Add type tests verifying tool compatibility with `generateText`/`streamText`

```typescript
// Before - causes ESLint "error typed value" warnings
export const webSearch_20250305 = (
  args: Parameters<typeof factory>[0] = {},
) => factory(args);

// After - clean type inference
export interface WebSearch20250305Options {
  maxUses?: number;
  allowedDomains?: string[];
  blockedDomains?: string[];
  userLocation?: { type: 'approximate'; city?: string; /* ... */ };
}

export const webSearch_20250305 = (
  args: WebSearch20250305Options = {},
) => factory(args);
```

