```

/**
 * Temporary workaround: injects OpenAI tool_search and defer_loading into the
 * request body via fetch interception, since @ai-sdk/openai doesn't support
 * these natively yet. Remove once the AI SDK adds native tool_search support.
 * https://developers.openai.com/api/docs/guides/tools-tool-search
 */
export const openaiToolSearchFetch = (async (
  input: RequestInfo | URL,
  init?: RequestInit,
) => {
  if (init?.method === "POST" && init.body) {
    try {
      const body = JSON.parse(init.body as string);

      if (Array.isArray(body.tools) && body.tools.length > 0) {
        const hasToolSearch = body.tools.some(
          (t: { type: string }) => t.type === "tool_search",
        );

        if (!hasToolSearch) {
          body.tools.push({ type: "tool_search" });
        }

        for (const tool of body.tools) {
          if (
            tool.type === "function" &&
            tool.name &&
            deferredTools.has(tool.name)
          ) {
            tool.defer_loading = true;
          }
        }

        init = { ...init, body: JSON.stringify(body) };
      }
    } catch {
      // not JSON or parse error — pass through unchanged
    }
  }

  return globalThis.fetch(input, init);
}) as typeof fetch;
```

